  function ceremonyPage(){return `${pageHead("开闭幕式","专属议程、嘉宾席位、场地物料与现场任务。",false)}<div class="grid-2"><section class="panel"><div class="panel-head"><h3>开幕式议程</h3><span class="badge green">12项已排定</span></div><div class="panel-body"><ul class="timeline"><li>领导与嘉宾签到<time>08:00</time></li><li>主办方致辞、裁判宣誓<time>08:30</time></li><li>竞赛正式启动<time>08:55</time></li></ul><button class="btn" data-action="ceremony-agenda">编辑议程与席位</button></div></section><section class="panel"><div class="panel-head"><h3>闭幕式与颁奖</h3><span class="badge orange">筹备中</span></div><div class="panel-body"><div class="detail-list"><dt>时间地点</dt><dd>08-20 15:00 · 主会场</dd><dt>奖项</dt><dd>个人奖、团体奖、优秀组织奖</dd><dt>物料</dt><dd>证书、奖杯、背景板、座次牌</dd><dt>发布前置</dt><dd>成绩复核完成且结果发布获批</dd></div><br><button class="btn" data-action="ceremony-material">核对物料与任务</button></div></section></div>`}
  function finalPage(){return `${pageHead("决赛配置","专属排期分组、裁判回避、实操成绩录入与复核。",false)}<div class="panel"><div class="panel-body"><span class="badge orange">待业务确认</span> 线上/线下决赛比例与实操评分方式尚未定稿。候选：理论30%+实操70%，或纯线下实操；实操候选为多裁判去极值/平均分。 <button class="text-btn" data-action="final-rule-candidate">选择候选方案</button></div></div><div class="grid-2"><section class="panel"><div class="panel-head"><h3>排期与分组</h3>${canWrite()?'<button class="btn primary" data-action="final-schedule">编排赛程</button>':""}</div><div class="panel-body"><table class="data-table"><tr><th>组别</th><th>时间/场地</th><th>选手</th><th>裁判</th></tr><tr><td>实操A组</td><td>08-18 08:30 / A区</td><td>10人</td><td>陈海峰等6人</td></tr><tr><td>实操B组</td><td>08-18 13:30 / B区</td><td>10人</td><td>刘志强等6人</td></tr></table></div></section><section class="panel"><div class="panel-head"><h3>裁判回避校验</h3><span class="badge red">1项冲突</span></div><div class="panel-body"><div class="detail-list"><dt>刘志强</dt><dd>同时参与决赛实操命题，候选为换组或仅承担非命题项目</dd><dt>陈海峰</dt><dd>无单位/指导关系冲突</dd></div><br><button class="btn danger" data-action="judge-conflict">处理回避冲突</button></div></section></div><section class="panel"><div class="panel-head"><h3>实操成绩</h3><div class="actions"><button class="btn" data-action="score-entry">录入/校验成绩</button><button class="btn primary" data-action="score-review">提交复核</button></div></div><div class="panel-body"><table class="data-table"><tr><th>选手</th><th>理论</th><th>实操</th><th>加扣分</th><th>合计</th><th>状态</th></tr><tr><td>张伟</td><td>93.0</td><td>90.2</td><td>0</td><td>91.32</td><td>${badge("已确认")}</td></tr><tr><td>李娜</td><td>91.5</td><td>85.3</td><td>+1</td><td>88.78</td><td>${badge("待复核")}</td></tr></table></div></section>`}
  function publicityPage(){return `${pageHead("结果公示","专属公示范围、异议受理与最终结果发布确认。",false)}<div class="grid-2"><section class="panel"><div class="panel-head"><h3>发布校验</h3><span class="badge orange">1项待完成</span></div><div class="panel-body"><div class="detail-list"><dt>成绩复核</dt><dd>19/20 已签认</dd><dt>个人信息脱敏</dt><dd>通过</dd><dt>异议受理期</dt><dd>5个工作日</dd><dt>公开范围</dt><dd>获奖人、企业、名次、公开成绩</dd></div></div></section><section class="panel"><div class="panel-head"><h3>公示与发布</h3><span class="badge gray">待发布</span></div><div class="panel-body"><p>发布后公开大屏与选手端同步展示，未公开成绩、预算和联系方式保持隐藏。</p><button class="btn" data-action="publicity-preview">预览公开结果</button> ${canWrite()?'<button class="btn primary" data-action="publish-result">确认发布结果</button>':""}</div></section></div>`}
  function workflowArchivePage(){return `${pageHead("流程归档","专属完整性校验、缺件处理、版本封存与归档包生成。",false)}<div class="kpi-grid"><article class="kpi"><label>流程节点</label><strong>9/9</strong><small>状态完整</small></article><article class="kpi"><label>任务</label><strong>164</strong><small>162已验收</small></article><article class="kpi"><label>成果</label><strong>286</strong><small>2份待补</small></article><article class="kpi"><label>完整度</label><strong>96%</strong><small>待最终封存</small></article></div><section class="panel"><div class="panel-head"><h3>归档校验清单</h3><span class="badge orange">2项待补</span></div><div class="panel-body"><div class="detail-list"><dt>计划/通知/流程版本</dt><dd>完整，可封存</dd><dt>成绩与复核签认</dt><dd>缺1份裁判签认单</dd><dt>预算与费用</dt><dd>完整，仅组织方与财务可见</dd><dt>影像与会议资料</dt><dd>缺闭幕式完整视频</dd></div><br><button class="btn" data-route="archive-center">查看档案中心</button> ${canWrite()?'<button class="btn primary" data-action="generate-archive">补齐后生成归档包</button>':""}</div></section>`}
  function specializedStagePage(id){return ({preliminary:preliminaryPage,semifinal:semifinalPage,ceremony:ceremonyPage,final:finalPage,"result-publicity":publicityPage,"workflow-archive":workflowArchivePage}[id]||preliminaryPage)()}
  function designerWithPending(){return designer().replace('<div class="toolbar"',`<div class="panel"><div class="panel-body"><span class="badge orange">待业务确认</span> 条件分支、节点审批、并行汇聚与回退深度尚未定稿。候选：一期仅单级审批/回退至上一步；二期支持多条件分支与任意历史节点回退。 <button class="text-btn" data-action="workflow-depth">配置候选深度</button></div></div><div class="toolbar"`)}
  function aiWithPending(){return ai().replace('<div class="ai-layout">',`<div class="panel"><div class="panel-body"><span class="badge orange">待业务确认</span> 双 AI 最终采用单入口自动路由还是流程/专业双入口。 <button class="text-btn" data-action="ai-entry-mode">选择候选入口</button></div></div><div class="ai-layout">`)}
  function kanban(){const cols=[["未开始",["确认决赛参会名单","制作选手胸牌"]],["进行中",["评分标准终审","实操设备联调"]],["待验收",["初赛成绩复核","场地平面图"]],["已完成",["技术文件定稿","专家签到归档"]]];return `${pageHead("任务看板","按状态跟踪跨角色任务，识别逾期与成果缺失。",false)}<div class="toolbar" style="margin-bottom:14px"><select class="select"><option>全部负责人</option></select><select class="select"><option>全部阶段</option></select><button class="btn primary" data-action="create-task">＋ 新建任务</button></div><div class="kanban">${cols.map((c,ci)=>`<section class="kanban-col"><h4>${c[0]} <span>${c[1].length}</span></h4>${c[1].map((t,i)=>`<article class="task-card" data-action="task-detail" data-name="${t}"><b>${t}</b><span class="badge ${ci===3?'green':ci===1?'orange':'gray'}">${c[0]}</span><p>${ci===0?'截止 07-'+(20+i*3):ci===1?'进度 '+(65+i*10)+'%':'已上传成果文件'}</p><div class="avatar-stack"><span>${['林','周','孙','王'][ci]}</span><span>${['李','陈','赵','刘'][i]}</span></div></article>`).join("")}</section>`).join("")}</div>`}
  function gantt(){const tasks=[["技术文件定稿",0,24],["初赛组织执行",12,25],["复赛成绩复核",36,18],["决赛设备准备",44,33],["开幕式筹备",55,25],["结果公示",82,14]];return `${pageHead("任务甘特图","查看任务时间跨度、依赖关系与关键路径。",false)}<section class="panel"><div class="panel-head"><h3>2026年6月 — 8月</h3><div class="actions"><button class="btn" data-action="today">今天</button><button class="btn" data-action="zoom">周 / 月</button></div></div><div class="panel-body table-wrap"><div class="gantt"><div class="gantt-row"><b>任务</b><div style="display:flex;justify-content:space-around;color:#7d899b"><span>6月</span><span>7月</span><span>8月</span></div></div>${tasks.map((x,i)=>`<div class="gantt-row"><button class="text-btn" data-action="task-detail" data-name="${x[0]}">${x[0]}</button><div class="gantt-track"><i class="gantt-bar" style="left:${x[1]}%;width:${x[2]}%;background:${i===3?'#f39b21':''}"></i></div></div>`).join("")}</div></div></section>`}
  function compare(){return `${pageHead("预算执行对比","按费用类别监控预算、合同、实际支出与偏差。",false)}<div class="kpi-grid"><article class="kpi"><label>预算总额</label><strong>¥864,000</strong><small>已审批</small></article><article class="kpi"><label>合同金额</label><strong>¥612,800</strong><small>70.9%</small></article><article class="kpi"><label>实际支出</label><strong>¥486,320</strong><small>56.3%</small></article><article class="kpi"><label>预计结余</label><strong>¥81,460</strong><small class="trend">节余 9.4%</small></article></div><section class="panel"><div class="panel-head"><h3>分类执行情况</h3><button class="btn" data-action="export">导出预算对比</button></div><div class="panel-body">${[["专家及裁判",186000,142000],["场地及设备",298000,201800],["物料及宣传",164000,118520],["接待及交通",136000,24000],["奖金及其他",80000,0]].map(x=>`<div class="progress-row" style="grid-template-columns:120px 1fr 180px"><span>${x[0]}</span><div class="progress"><i style="width:${Math.round(x[2]/x[1]*100)}%;background:${x[2]/x[1]>.85?'var(--orange)':'var(--blue)'}"></i></div><b>¥${x[2].toLocaleString()} / ¥${x[1].toLocaleString()}</b></div>`).join("")}</div></section>`}
  function archive(){const files=[["竞赛计划与通知","18份","100%"],["技术研讨档案","42份","100%"],["报名与人员档案","86份","98%"],["试题与试卷密档","28份","100%"],["成绩与获奖档案","16份","72%"],["费用与合同档案","34份","86%"],["现场影像资料","286份","64%"],["任务执行记录","164项","96%"]];return `${pageHead("档案中心","按赛事全生命周期汇聚文件、数据、过程记录和审计留痕。",false)}<div class="archive-grid">${files.map((x,i)=>`<article class="file-card"><div class="file-icon">${['计','研','人','题','绩','费','像','任'][i]}</div><h4>${x[0]}</h4><p>${x[1]} · 完整度 ${x[2]}</p><div class="progress"><i style="width:${x[2]}"></i></div><br><button class="text-btn" data-action="view-archive" data-name="${x[0]}">进入档案</button></article>`).join("")}</div>`}
  function exportCenter(){return `${pageHead("一键归档导出","选择归档范围，生成带目录、校验清单与访问水印的赛事档案包。",false)}<section class="panel"><div class="panel-head"><h3>归档导出配置</h3><span class="badge green">数据校验 96%</span></div><div class="panel-body"><div class="form-grid">${["竞赛计划与通知","流程与任务记录","报名及人员名单","专家与命题记录","成绩排名获奖","预算及费用","会议资料","照片与视频"].map(x=>`<label class="template-card"><input type="checkbox" checked> <b>${x}</b><p>包含文件、数据表和操作日志</p></label>`).join("")}</div><div class="wizard-foot"><span>预计 2.8GB · 敏感文件自动加密</span><button class="btn primary" data-action="generate-archive">生成归档包</button></div></div></section>`}
  function ai(){return `${pageHead("AI 助手配置","配置赛事流程助手与专业知识助手的知识、权限和回答边界。",false)}<div class="ai-layout"><div><article class="assistant-card active"><span class="badge green">已启用</span><h3>竞赛流程助手</h3><p>通知、报名、时间、地点、任务、成绩与晋级规则。</p><button class="text-btn" data-action="edit-ai">编辑配置</button></article><br><article class="assistant-card"><span class="badge green">已启用</span><h3>专业知识助手</h3><p>技术文件、竞赛大纲、学习资料及已公开题目解析。</p><button class="text-btn" data-action="edit-ai">编辑配置</button></article></div><div class="chat-demo"><div class="bubble">你好，我是本届竞赛流程助手。可以询问报名、赛程、个人任务和成绩。</div><div class="bubble mine">我的决赛时间和地点是什么？</div><div class="bubble">你已晋级决赛。比赛时间为 8月18日 08:30，地点为实操区A。请提前30分钟签到。</div><div class="chat-input"><input class="input" placeholder="输入问题测试回答效果"><button class="btn primary" data-action="test-ai">发送测试</button></div></div></div>`}
  function renderPage(id){if(!pageNames[id]){id="dashboard";if(location.hash!=="#dashboard")history.replaceState(null,"","#dashboard");toast("无效页面地址，已返回数据驾驶舱")}if(!canAccess(id)){id=currentRole==="财务审核员"?"budget-detail":"dashboard";history.replaceState(null,"",`#${id}`);toast(`权限限制：${roleRules[currentRole].scope}`)}currentPage=id;crumb.textContent=pageNames[id];document.title=`${crumb.textContent} · 竞赛运营中心`;document.querySelectorAll(".nav-item").forEach(el=>{el.classList.toggle("active",el.dataset.route===id);if(el.dataset.route===id)el.closest(".nav-group").classList.add("open")});const specials={dashboard,"competition-create":createCompetition,notice:noticePage,"workflow-template":templates,"workflow-designer":designerWithPending,"node-config":nodeConfig,seminar:seminarPage,"task-kanban":kanban,"task-gantt":gantt,"budget-compare":compare,"archive-center":archive,"export-center":exportCenter,"ai-assistant":aiWithPending};if(specials[id])content.innerHTML=specials[id]();else if(["preliminary","semifinal","ceremony","final","result-publicity","workflow-archive"].includes(id))content.innerHTML=specializedStagePage(id);else content.innerHTML=tablePage(id);enhanceCompetitionWizard();window.scrollTo(0,0)}

